spec.setup_code:
var cubeGeo = new api.THREE.BoxGeometry(1, 1, 1);
                var cubeMat = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(cubeGeo, cubeMat);
                api.group.add(cube);
                var speed = 0.03;
                var range = 2.5;
                return {
                  update: function(t) {
                    cube.position.x = Math.sin(t * speed) * range;
                    cube.rotation.y = t * 0.01;
                  }
                };

var x = 0;
                var dir = 1;
                var speedPxPerSec = 90;
                return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);

                    var groundY = H / 2 + 60;
                    ctx.strokeStyle = '#C9C2B4';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(0, groundY);
                    ctx.lineTo(W, groundY);
                    ctx.stroke();

                    x += dir * speedPxPerSec * (dt || 0.016);
                    var margin = 40;
                    if (x > W - margin) { x = W - margin; dir = -1; }
                    if (x < margin) { x = margin; dir = 1; }

                    var carY = groundY - 18;
                    ctx.fillStyle = '#E8593C';
                    ctx.fillRect(x - 25, carY - 12, 50, 24);
                    ctx.beginPath();
                    ctx.arc(x - 15, carY + 12, 7, 0, Math.PI * 2);
                    ctx.arc(x + 15, carY + 12, 7, 0, Math.PI * 2);
                    ctx.fillStyle = '#333333';
                    ctx.fill();

                    var arrowLen = 45;
                    var arrowY = carY - 30;
                    ctx.strokeStyle = '#2563EB';
                    ctx.lineWidth = 4;
                    ctx.beginPath();
                    ctx.moveTo(x, arrowY);
                    ctx.lineTo(x + dir * arrowLen, arrowY);
                    ctx.stroke();
                    ctx.beginPath();
                    ctx.moveTo(x + dir * arrowLen, arrowY);
                    ctx.lineTo(x + dir * (arrowLen - 10), arrowY - 6);
                    ctx.lineTo(x + dir * (arrowLen - 10), arrowY + 6);
                    ctx.closePath();
                    ctx.fillStyle = '#2563EB';
                    ctx.fill();

                    ctx.fillStyle = '#333333';
                    ctx.font = '14px sans-serif';
                    ctx.fillText('v = ' + (dir > 0 ? '+' : '-') + '90 px/s (velocity vector shown in blue)', 16, 24);
                  }
                };

var x = 0;
                var curV = 2;
                return {
                  init: function(api) {
                    x = api.width / 2;
                  },
                  onControlChange: function(id, val) {
                    if (id === 'velocity') { curV = val; }
                  },
                  update: function(dt, time, state) {
                    curV = (state.velocity !== undefined) ? state.velocity : curV;
                    x += curV * 40 * dt;
                    if (x > 2000) x = -50;
                    if (x < -50) x = 2000;
                  },
                  draw: function(ctx, W, H) {
                    ctx.fillStyle = '#F9FAFB';
                    ctx.fillRect(0, 0, W, H);
                    var y = H / 2;
                    ctx.strokeStyle = '#E5E7EB';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(0, y + 30);
                    ctx.lineTo(W, y + 30);
                    ctx.stroke();

                    ctx.fillStyle = '#EC4899';
                    ctx.beginPath();
                    ctx.arc(x, y, 16, 0, Math.PI * 2);
                    ctx.fill();

                    var dir = curV >= 0 ? 1 : -1;
                    var len = Math.min(Math.abs(curV) * 12, 70);
                    ctx.strokeStyle = '#2563EB';
                    ctx.lineWidth = 4;
                    ctx.beginPath();
                    ctx.moveTo(x, y - 30);
                    ctx.lineTo(x + dir * len, y - 30);
                    ctx.stroke();

                    ctx.fillStyle = '#111827';
                    ctx.font = '14px sans-serif';
                    ctx.fillText('v = ' + curV.toFixed(1) + ' m/s', 16, 24);
                  }
                };
